import React, { useCallback, useEffect, useRef } from 'react';

const ToastContainer = ({ toasts, setToasts }) => {
  // Referencia para evitar race conditions en el timeout
  const toastsRef = useRef(toasts);
  useEffect(() => { toastsRef.current = toasts; }, [toasts]);

  // Auto-eliminación segura de cada toast
  useEffect(() => {
    if (toasts.length === 0) return;
    // Solo setear timeout para el toast más reciente
    const latest = toasts[toasts.length - 1];
    const timeout = setTimeout(() => {
      setToasts((prev) => prev.filter((t) => t.id !== latest.id));
    }, 3000);
    return () => clearTimeout(timeout);
  }, [toasts, setToasts]);

  const removeToast = useCallback(
    (id) => {
      setToasts((prev) => prev.filter((t) => t.id !== id));
    },
    [setToasts]
  );

  return (
    <div className="fixed top-4 right-4 z-50 flex flex-col gap-2">
      {toasts.map((toast) => (
        <div
          key={toast.id}
          className={`flex items-start min-w-[250px] max-w-[350px] px-4 py-3 rounded shadow-lg bg-white border-l-4 ${
            toast.type === 'success'
              ? 'border-green-500'
              : toast.type === 'error'
              ? 'border-red-500'
              : 'border-yellow-400'
          }`}
        >
          <div className={`flex items-center justify-center w-6 h-6 rounded-full mr-3 ${
            toast.type === 'success'
              ? 'bg-green-500 text-white'
              : toast.type === 'error'
              ? 'bg-red-500 text-white'
              : 'bg-yellow-400 text-white'
          }`}>
            <i className={`bi ${toast.type === 'success' ? 'bi-check-lg' : toast.type === 'error' ? 'bi-x-lg' : 'bi-exclamation-lg'}`}></i>
          </div>
          <div className="flex-1">
            <div className="font-bold">{toast.title}</div>
            <div className="text-sm">{toast.message}</div>
          </div>
          <button
            className="ml-4 text-gray-500 hover:text-gray-800 text-xl font-bold focus:outline-none"
            onClick={() => removeToast(toast.id)}
          >
            ×
          </button>
        </div>
      ))}
    </div>
  );
};

export default ToastContainer;
